        add.accept("chain.supernaturalcraft.voice.hunter.sight_again.any.0", "%1$s. Still making terrible travel plans?");
        add.accept("chain.supernaturalcraft.voice.hunter.sight_again.any.1", "I remember you. My ribs remember better.");
        add.accept("chain.supernaturalcraft.voice.hunter.sight_again.any.2", "Same face. Please tell me you learned something.");
