        add.accept("chain.supernaturalcraft.voice.hunter.kill_hunter.any.1", "Another name I didn't want to learn.");
        add.accept("chain.supernaturalcraft.voice.hunter.kill_hunter.any.2", "You made your choice. Hell of a waste.");
