        add.accept("chain.supernaturalcraft.voice.hunter.return_scarred.any.2", "Takes more than that to end a bad habit.");
        add.accept("chain.supernaturalcraft.voice.hunter.return_scarred.any.3", "The road wasn't done with me.");
        add.accept("chain.supernaturalcraft.voice.hunter.return_scarred.any.4", "Next time, check the pulse.");
        add.accept("chain.supernaturalcraft.voice.hunter.challenge_issued.any.0", "You, me, and no audience participation.");
        add.accept("chain.supernaturalcraft.voice.hunter.challenge_issued.any.1", "%1$s, let's settle this before supper.");
        add.accept("chain.supernaturalcraft.voice.hunter.challenge_issued.any.2", "%2$s, bring your blade and leave the excuses.");
