        add.accept("chain.supernaturalcraft.voice.hunter.challenge_issued.any.4", "One duel. Save everyone the paperwork.");
        add.accept("chain.supernaturalcraft.voice.hunter.duel_start.any.0", "All right. Let's earn the bruises.");
        add.accept("chain.supernaturalcraft.voice.hunter.duel_start.any.1", "No tricks from the cheap seats.");
        add.accept("chain.supernaturalcraft.voice.hunter.duel_start.any.2", "I've had worse mornings. Probably.");
