        add.accept("chain.supernaturalcraft.voice.hunter.duel_lost.any.4", "One road too many.");
        add.accept("chain.supernaturalcraft.voice.hunter.yield.any.0", "Enough. I know when I'm beat.");
        add.accept("chain.supernaturalcraft.voice.hunter.yield.any.1", "Your win. My dentist sends his thanks.");
