        add.accept("chain.supernaturalcraft.voice.hunter.yield.any.4", "All right, you earned it.");
        add.accept("chain.supernaturalcraft.voice.hunter.feud_taunt.any.0", "%2$s, your rank's doing all the heavy lifting.");
        add.accept("chain.supernaturalcraft.voice.hunter.feud_taunt.any.1", "I've seen scarecrows hold a post better.");
        add.accept("chain.supernaturalcraft.voice.hunter.feud_taunt.any.2", "Big speech. Shame about the footwork.");
        add.accept("chain.supernaturalcraft.voice.hunter.feud_taunt.any.3", "%2$s, try earning the chair for once.");
        add.accept("chain.supernaturalcraft.voice.hunter.feud_taunt.any.4", "You want respect? Start with showing up.");
        add.accept("chain.supernaturalcraft.voice.hunter.skirmish_cry.any.0", "Hold the line. We paid for those boots.");
        add.accept("chain.supernaturalcraft.voice.hunter.skirmish_cry.any.1", "For the guild. And a quiet drive home.");
        add.accept("chain.supernaturalcraft.voice.hunter.skirmish_cry.any.2", "Eyes open. Even the one who used to have wings.");
