        add.accept("chain.supernaturalcraft.voice.hunter.skirmish_cry.any.4", "Push them back. Then we get coffee.");
        add.accept("chain.supernaturalcraft.voice.hunter.vow.any.0", "%2$s made this personal. We send our best.");
        add.accept("chain.supernaturalcraft.voice.hunter.vow.any.1", "A champion, one fight, and %2$s answers for it.");
