        add.accept("chain.supernaturalcraft.voice.hunter.greet_ally.any.1", "Our colours buy you a minute. Talk.");
        add.accept("chain.supernaturalcraft.voice.hunter.greet_ally.any.2", "Need something, or just avoiding guard duty?");
        add.accept("chain.supernaturalcraft.voice.hunter.greet_parley.any.0", "Hands where I can see them. Then we talk.");
        add.accept("chain.supernaturalcraft.voice.hunter.greet_parley.any.1", "I've heard worse ideas than talking. Go on.");
        add.accept("chain.supernaturalcraft.voice.hunter.greet_parley.any.2", "A truce long enough for a sentence. Make it good.");
        add.accept("chain.supernaturalcraft.voice.hunter.parley_refuse.any.0", "No. I've buried people who trusted that smile.");
        add.accept("chain.supernaturalcraft.voice.hunter.parley_refuse.any.1", "Keep walking. That's the friendly version.");
        add.accept("chain.supernaturalcraft.voice.hunter.parley_refuse.any.2", "You don't get a hearing today.");
        add.accept("chain.supernaturalcraft.voice.hunter.rumor.any.0", "%2$s was spotted %3$s. Pack something sharp.");
        add.accept("chain.supernaturalcraft.voice.hunter.rumor.any.1", "Last word on %2$s: %3$s. Check your exits.");
        add.accept("chain.supernaturalcraft.voice.hunter.rumor.any.2", "Try %3$s for %2$s. I wouldn't go alone.");
        add.accept("chain.supernaturalcraft.voice.hunter.rumor_none.any.0", "Nothing worth burning fuel over.");
        add.accept("chain.supernaturalcraft.voice.hunter.rumor_none.any.1", "No names. Quiet's suspicious, but I'll take it.");
        add.accept("chain.supernaturalcraft.voice.hunter.rumor_none.any.2", "If I hear something, you'll hear the swearing.");
        add.accept("chain.supernaturalcraft.voice.hunter.pact_yes.any.0", "Deal. You cover my back, I cover yours.");
        add.accept("chain.supernaturalcraft.voice.hunter.pact_yes.any.1", "All right. A promise beats another funeral.");
        add.accept("chain.supernaturalcraft.voice.hunter.pact_yes.any.2", "You've got my word. Don't make me regret it.");
