        add.accept("chain.supernaturalcraft.voice.hunter.aid_yes.any.1", "Fine. Nobody should face that alone.");
        add.accept("chain.supernaturalcraft.voice.hunter.aid_yes.any.2", "Count me in. You did the same for me.");
