        add.accept("chain.supernaturalcraft.voice.hunter.skirmish_cry.cruel.0", "Hold the line. Break them slowly.");
        add.accept("chain.supernaturalcraft.voice.hunter.vow.cruel.0", "%2$s will answer for this. Our champion will make it hurt.");
        add.accept("chain.supernaturalcraft.voice.hunter.greet_ally.cruel.0", "Good to see our colours. Got any ugly news? I like ugly.");
        add.accept("chain.supernaturalcraft.voice.hunter.greet_parley.cruel.0", "You get one minute. Begging might improve it.");
        add.accept("chain.supernaturalcraft.voice.hunter.parley_refuse.cruel.0", "Keep walking. I liked you better scared.");
        add.accept("chain.supernaturalcraft.voice.hunter.audience_greet.cruel.0", "You found my chair. Who needs a lesson today?");
        add.accept("chain.supernaturalcraft.voice.hunter.coward.cruel.0", "No duel, then. Shame. I sharpened everything.");
        add.accept("chain.supernaturalcraft.voice.hunter.sight_foe.cunning.0", "Enemy ahead. Already checked your exits.");
        add.accept("chain.supernaturalcraft.voice.hunter.sight_again.cunning.0", "You again. I studied your last mistake.");
        add.accept("chain.supernaturalcraft.voice.hunter.sight_ally.cunning.0", "Same colours. Keep the plan between us.");
        add.accept("chain.supernaturalcraft.voice.hunter.kill_hunter.cunning.0", "Fight is over. Less noise than I expected.");
        add.accept("chain.supernaturalcraft.voice.hunter.flee.cunning.0", "Falling back. Always leave a second exit.");
        add.accept("chain.supernaturalcraft.voice.hunter.return_scarred.cunning.0", "Back on the road. I learned which door stays open.");
        add.accept("chain.supernaturalcraft.voice.hunter.challenge_issued.cunning.0", "Meet me in the ring. Your choice of ground tells plenty.");
        add.accept("chain.supernaturalcraft.voice.hunter.duel_start.cunning.0", "Blades up. I already counted the witnesses.");
        add.accept("chain.supernaturalcraft.voice.hunter.duel_won.cunning.0", "My win. Preparation beats a fancy title.");
        add.accept("chain.supernaturalcraft.voice.hunter.duel_lost.cunning.0", "End of my road. Missed one angle. Just one.");
        add.accept("chain.supernaturalcraft.voice.hunter.yield.cunning.0", "I yield. Better odds another day.");
        add.accept("chain.supernaturalcraft.voice.hunter.feud_taunt.cunning.0", "Come on, %2$s. Your friends talk cheaply.");
        add.accept("chain.supernaturalcraft.voice.hunter.skirmish_cry.cunning.0", "Hold the line. Take the flank while they watch me.");
        add.accept("chain.supernaturalcraft.voice.hunter.vow.cunning.0", "%2$s will answer for this. I'll pick the champion carefully.");
        add.accept("chain.supernaturalcraft.voice.hunter.greet_ally.cunning.0", "Good to see our colours. Speak low. The walls have payroll.");
        add.accept("chain.supernaturalcraft.voice.hunter.greet_parley.cunning.0", "You get one minute. An offer is useful information.");
        add.accept("chain.supernaturalcraft.voice.hunter.parley_refuse.cunning.0", "Keep walking. I know what you're fishing for.");
        add.accept("chain.supernaturalcraft.voice.hunter.audience_greet.cunning.0", "You found my chair. Start with what you left out.");
        add.accept("chain.supernaturalcraft.voice.hunter.coward.cunning.0", "No duel, then. Now I know your price.");
        add.accept("chain.supernaturalcraft.voice.hunter.sight_foe.proud.0", "Enemy ahead. You picked the wrong veteran.");
        add.accept("chain.supernaturalcraft.voice.hunter.sight_again.proud.0", "You again. Still haven't learned my name?");
        add.accept("chain.supernaturalcraft.voice.hunter.sight_ally.proud.0", "Same colours. I earned these colours.");
        add.accept("chain.supernaturalcraft.voice.hunter.kill_hunter.proud.0", "Fight is over. Should've respected the mileage.");
        add.accept("chain.supernaturalcraft.voice.hunter.flee.proud.0", "Falling back. You haven't beaten me yet.");
        add.accept("chain.supernaturalcraft.voice.hunter.return_scarred.proud.0", "Back on the road. Scars aren't apologies.");
        add.accept("chain.supernaturalcraft.voice.hunter.challenge_issued.proud.0", "Meet me in the ring. Let's see you earn that mouth.");
        add.accept("chain.supernaturalcraft.voice.hunter.duel_start.proud.0", "Blades up. Watch how a veteran works.");
        add.accept("chain.supernaturalcraft.voice.hunter.duel_won.proud.0", "My win. Experience. Try getting some.");
        add.accept("chain.supernaturalcraft.voice.hunter.duel_lost.proud.0", "End of my road. I won't beg for the ending.");
        add.accept("chain.supernaturalcraft.voice.hunter.yield.proud.0", "I yield. You earned this one. Only this one.");
        add.accept("chain.supernaturalcraft.voice.hunter.feud_taunt.proud.0", "Come on, %2$s. Rank isn't a substitute for skill.");
        add.accept("chain.supernaturalcraft.voice.hunter.skirmish_cry.proud.0", "Hold the line. Show them what our colours mean.");
        add.accept("chain.supernaturalcraft.voice.hunter.vow.proud.0", "%2$s will answer for this. Our name deserves an answer.");
        add.accept("chain.supernaturalcraft.voice.hunter.greet_ally.proud.0", "Good to see our colours. Wipe your boots before you talk.");
        add.accept("chain.supernaturalcraft.voice.hunter.greet_parley.proud.0", "You get one minute. Keep the cheap threats outside.");
        add.accept("chain.supernaturalcraft.voice.hunter.parley_refuse.proud.0", "Keep walking. I won't hear that tone.");
        add.accept("chain.supernaturalcraft.voice.hunter.audience_greet.proud.0", "You found my chair. Respect the work behind this chair.");
        add.accept("chain.supernaturalcraft.voice.hunter.coward.proud.0", "No duel, then. You wasted a veteran's time.");
        add.accept("chain.supernaturalcraft.voice.hunter.sight_foe.zealous.0", "Enemy ahead. The guild holds this road.");
        add.accept("chain.supernaturalcraft.voice.hunter.sight_again.zealous.0", "You again. You won't break our purpose.");
        add.accept("chain.supernaturalcraft.voice.hunter.sight_ally.zealous.0", "Same colours. Keep faith with the living.");
        add.accept("chain.supernaturalcraft.voice.hunter.kill_hunter.zealous.0", "Fight is over. One less threat to our people.");
        add.accept("chain.supernaturalcraft.voice.hunter.flee.zealous.0", "Falling back. Living serves the cause better.");
        add.accept("chain.supernaturalcraft.voice.hunter.return_scarred.zealous.0", "Back on the road. Still got people to protect.");
        add.accept("chain.supernaturalcraft.voice.hunter.challenge_issued.zealous.0", "Meet me in the ring. We settle who holds the line.");
        add.accept("chain.supernaturalcraft.voice.hunter.duel_start.zealous.0", "Blades up. The standard stays standing.");
        add.accept("chain.supernaturalcraft.voice.hunter.duel_won.zealous.0", "My win. Our cause holds.");
        add.accept("chain.supernaturalcraft.voice.hunter.duel_lost.zealous.0", "End of my road. Keep the guild alive.");
        add.accept("chain.supernaturalcraft.voice.hunter.yield.zealous.0", "I yield. The guild needs us both alive.");
        add.accept("chain.supernaturalcraft.voice.hunter.feud_taunt.zealous.0", "Come on, %2$s. You forgot what we stand for.");
        add.accept("chain.supernaturalcraft.voice.hunter.skirmish_cry.zealous.0", "Hold the line. For everyone under our standard!");
        add.accept("chain.supernaturalcraft.voice.hunter.vow.zealous.0", "%2$s will answer for this. Our champion carries our promise.");
        add.accept("chain.supernaturalcraft.voice.hunter.greet_ally.zealous.0", "Good to see our colours. Tell me how this helps the guild.");
        add.accept("chain.supernaturalcraft.voice.hunter.greet_parley.zealous.0", "You get one minute. Speak plainly about your purpose.");
        add.accept("chain.supernaturalcraft.voice.hunter.parley_refuse.zealous.0", "Keep walking. Our cause isn't for sale.");
        add.accept("chain.supernaturalcraft.voice.hunter.audience_greet.zealous.0", "You found my chair. The guild comes before the chair.");
        add.accept("chain.supernaturalcraft.voice.hunter.coward.zealous.0", "No duel, then. A promise means showing up.");
        add.accept("chain.supernaturalcraft.voice.demon.hire_offer.any.0", "%3$s. A bargain, considering the teeth.");
        add.accept("chain.supernaturalcraft.voice.demon.hire_offer.any.1", "My price is %3$s. Your soul can stay where it is.");
        add.accept("chain.supernaturalcraft.voice.demon.hire_offer.any.2", "%3$s buys my blade. Affection costs extra.");
        add.accept("chain.supernaturalcraft.voice.demon.hire_yes.any.0", "%2$s has bought itself a very useful problem.");
        add.accept("chain.supernaturalcraft.voice.demon.hire_yes.any.1", "Paid in full. I serve %2$s.");
        add.accept("chain.supernaturalcraft.voice.demon.hire_yes.any.2", "For %2$s, then. Keep the receipts.");
        add.accept("chain.supernaturalcraft.voice.demon.hire_no.any.0", "Empty pockets or a full roster. Either way, no deal.");
        add.accept("chain.supernaturalcraft.voice.demon.hire_no.any.1", "You haven't met the terms, meatsuit.");
        add.accept("chain.supernaturalcraft.voice.demon.hire_no.any.2", "Come back with a payable offer.");
        add.accept("chain.supernaturalcraft.voice.demon.recruit_yes.any.0", "Beat me and %2$s gets my blade. Lose, and I get a laugh.");
        add.accept("chain.supernaturalcraft.voice.demon.recruit_yes.any.1", "My allegiance on the table, %2$s on the contract. Draw.");
        add.accept("chain.supernaturalcraft.voice.demon.recruit_yes.any.2", "One duel for my service to %2$s. I accept.");
        add.accept("chain.supernaturalcraft.voice.demon.recruit_no.any.0", "I don't gamble my career on a hunter's tantrum.");
        add.accept("chain.supernaturalcraft.voice.demon.recruit_no.any.1", "My present arrangement pays better than your odds.");
        add.accept("chain.supernaturalcraft.voice.demon.recruit_no.any.2", "No. Find a cheaper traitor.");
        add.accept("chain.supernaturalcraft.voice.demon.desert.any.0", "%2$s gets me at %3$s. What a humiliating discount.");
        add.accept("chain.supernaturalcraft.voice.demon.desert.any.1", "A loss is a loss. I serve %2$s as %3$s.");
        add.accept("chain.supernaturalcraft.voice.demon.desert.any.2", "%3$s under %2$s. I hope the perks survive the demotion.");
        add.accept("chain.supernaturalcraft.voice.demon.bound.any.0", "My name, your leash. I serve %2$s.");
        add.accept("chain.supernaturalcraft.voice.demon.bound.any.1", "%2$s has my oath. Don't mistake it for gratitude.");
        add.accept("chain.supernaturalcraft.voice.demon.bound.any.2", "Bound to %2$s. I will remember who held the book.");
        add.accept("chain.supernaturalcraft.voice.angel.hire_offer.any.0", "%3$s is the offering required for my service.");
        add.accept("chain.supernaturalcraft.voice.angel.hire_offer.any.1", "Provide %3$s, and I shall consider your standard.");
        add.accept("chain.supernaturalcraft.voice.angel.hire_offer.any.2", "My service requires %3$s. The terms are plain.");
        add.accept("chain.supernaturalcraft.voice.angel.hire_yes.any.0", "The offering is received. I shall serve %2$s.");
        add.accept("chain.supernaturalcraft.voice.angel.hire_yes.any.1", "I take my station beneath the standard of %2$s.");
        add.accept("chain.supernaturalcraft.voice.angel.hire_yes.any.2", "Let my service to %2$s be witnessed.");
        add.accept("chain.supernaturalcraft.voice.angel.hire_no.any.0", "The conditions of service remain unmet.");
        add.accept("chain.supernaturalcraft.voice.angel.hire_no.any.1", "There is no station for me under these terms.");
        add.accept("chain.supernaturalcraft.voice.angel.hire_no.any.2", "Your petition cannot be granted.");
        add.accept("chain.supernaturalcraft.voice.angel.recruit_yes.any.0", "I accept judgment by combat, and service to %2$s if I fall.");
        add.accept("chain.supernaturalcraft.voice.angel.recruit_yes.any.1", "Should you prevail, my oath shall pass to %2$s.");
        add.accept("chain.supernaturalcraft.voice.angel.recruit_yes.any.2", "For my allegiance to %2$s, then: let the trial begin.");
        add.accept("chain.supernaturalcraft.voice.angel.recruit_no.any.0", "My oath is not yours to wager.");
        add.accept("chain.supernaturalcraft.voice.angel.recruit_no.any.1", "I shall not submit my allegiance to this trial.");
        add.accept("chain.supernaturalcraft.voice.angel.recruit_no.any.2", "Such a challenge has no claim upon me.");
        add.accept("chain.supernaturalcraft.voice.angel.desert.any.0", "The trial is ended. I serve %2$s at the station of %3$s.");
        add.accept("chain.supernaturalcraft.voice.angel.desert.any.1", "As %3$s, I swear my service to %2$s.");
        add.accept("chain.supernaturalcraft.voice.angel.desert.any.2", "My defeat binds my word: %2$s shall have me as %3$s.");
        add.accept("chain.supernaturalcraft.voice.angel.bound.any.0", "The rite compels my service to %2$s. My assent was not sought.");
        add.accept("chain.supernaturalcraft.voice.angel.bound.any.1", "I am bound to %2$s by the name you have profaned.");
        add.accept("chain.supernaturalcraft.voice.angel.bound.any.2", "%2$s shall have obedience. My judgment remains my own.");
        add.accept("chain.supernaturalcraft.voice.fallen.hire_offer.any.0", "%3$s. Grace doesn't pay for supper anymore.");
        add.accept("chain.supernaturalcraft.voice.fallen.hire_offer.any.1", "I ask %3$s. Less than Heaven asked of me.");
        add.accept("chain.supernaturalcraft.voice.fallen.hire_offer.any.2", "%3$s for my service. At least this price is spoken aloud.");
        add.accept("chain.supernaturalcraft.voice.fallen.hire_yes.any.0", "%2$s, then. Another home to try not to lose.");
        add.accept("chain.supernaturalcraft.voice.fallen.hire_yes.any.1", "I'll serve %2$s. No hymns in the contract, I hope.");
        add.accept("chain.supernaturalcraft.voice.fallen.hire_yes.any.2", "Paid, and wanted. %2$s already improves on Heaven.");
        add.accept("chain.supernaturalcraft.voice.fallen.hire_no.any.0", "Not even exile makes that offer enough.");
        add.accept("chain.supernaturalcraft.voice.fallen.hire_no.any.1", "No place, no payment, no new oath.");
        add.accept("chain.supernaturalcraft.voice.fallen.hire_no.any.2", "I've served empty promises before.");
        add.accept("chain.supernaturalcraft.voice.fallen.recruit_yes.any.0", "Win, and I serve %2$s. I've changed skies before.");
        add.accept("chain.supernaturalcraft.voice.fallen.recruit_yes.any.1", "My blade for %2$s if yours proves better. Agreed.");
        add.accept("chain.supernaturalcraft.voice.fallen.recruit_yes.any.2", "A duel for a place in %2$s. Almost an honest way to fall.");
        add.accept("chain.supernaturalcraft.voice.fallen.recruit_no.any.0", "One Fall taught me enough about wagers.");
        add.accept("chain.supernaturalcraft.voice.fallen.recruit_no.any.1", "I'm not shedding another oath for your amusement.");
        add.accept("chain.supernaturalcraft.voice.fallen.recruit_no.any.2", "No. Even the fallen choose where they stand.");
        add.accept("chain.supernaturalcraft.voice.fallen.desert.any.0", "%3$s in %2$s. I've fallen further for less.");
        add.accept("chain.supernaturalcraft.voice.fallen.desert.any.1", "You won. %2$s has my blade, and %3$s has my name.");
        add.accept("chain.supernaturalcraft.voice.fallen.desert.any.2", "I serve %2$s as %3$s. Another rung lost, another sky.");
        add.accept("chain.supernaturalcraft.voice.fallen.bound.any.0", "%2$s has my name in chains. Heaven would recognise the method.");
        add.accept("chain.supernaturalcraft.voice.fallen.bound.any.1", "Bound to %2$s. I had hoped the next oath would be mine.");
        add.accept("chain.supernaturalcraft.voice.fallen.bound.any.2", "I serve %2$s. Freedom was a short chapter.");
        add.accept("chain.supernaturalcraft.voice.hunter.hire_offer.any.0", "%3$s. Fuel, ammo, and the privilege of my company.");
        add.accept("chain.supernaturalcraft.voice.hunter.hire_offer.any.1", "My price is %3$s. Cheaper than another funeral.");
        add.accept("chain.supernaturalcraft.voice.hunter.hire_offer.any.2", "%3$s gets me on the payroll. Demons still make me twitch.");
        add.accept("chain.supernaturalcraft.voice.hunter.hire_yes.any.0", "%2$s has a hunter. Please tell me there's coffee.");
        add.accept("chain.supernaturalcraft.voice.hunter.hire_yes.any.1", "Paid up. I'll watch the road for %2$s.");
        add.accept("chain.supernaturalcraft.voice.hunter.hire_yes.any.2", "I serve %2$s. Doesn't mean I trust the angel at breakfast.");
        add.accept("chain.supernaturalcraft.voice.hunter.hire_no.any.0", "Can't pay or can't fit me. Either way, I'm walking.");
        add.accept("chain.supernaturalcraft.voice.hunter.hire_no.any.1", "Come back when the job actually has a place for me.");
        add.accept("chain.supernaturalcraft.voice.hunter.hire_no.any.2", "Promises don't buy salt.");
        add.accept("chain.supernaturalcraft.voice.hunter.recruit_yes.any.0", "Beat me and I work for %2$s. Keep it clean.");
        add.accept("chain.supernaturalcraft.voice.hunter.recruit_yes.any.1", "One duel, my service to %2$s. I've taken worse jobs.");
        add.accept("chain.supernaturalcraft.voice.hunter.recruit_yes.any.2", "Fine. %2$s gets me if you win. Draw.");
        add.accept("chain.supernaturalcraft.voice.hunter.recruit_no.any.0", "Not betting my people on your sword arm.");
        add.accept("chain.supernaturalcraft.voice.hunter.recruit_no.any.1", "No. Some promises outlast a bad shift.");
        add.accept("chain.supernaturalcraft.voice.hunter.recruit_no.any.2", "Find another hunter. I'm staying put.");
        add.accept("chain.supernaturalcraft.voice.hunter.desert.any.0", "%3$s in %2$s. Guess I earned the pay cut.");
        add.accept("chain.supernaturalcraft.voice.hunter.desert.any.1", "You won. I serve %2$s as %3$s. Try not to gloat.");
        add.accept("chain.supernaturalcraft.voice.hunter.desert.any.2", "All right. %2$s, rank %3$s. Where do I put my bag?");
        add.accept("chain.supernaturalcraft.voice.hunter.bound.any.0", "You put my name in a rite. %2$s better be worth it.");
        add.accept("chain.supernaturalcraft.voice.hunter.bound.any.1", "I serve %2$s. We are going to have words about the leash.");
        add.accept("chain.supernaturalcraft.voice.hunter.bound.any.2", "Bound to %2$s. That's a hell of a recruitment policy.");
        add.accept("chain.supernaturalcraft.backstory.hunter.origin.0", "%1$s grew up beside a road nobody took after dark.");
        add.accept("chain.supernaturalcraft.backstory.hunter.origin.1", "%1$s learned the trade from a parent's unfinished journal.");
        add.accept("chain.supernaturalcraft.backstory.hunter.origin.2", "%1$s survived a nest that left an entire town silent.");
        add.accept("chain.supernaturalcraft.backstory.hunter.origin.3", "%1$s started hunting after a familiar face wore the wrong eyes.");
        add.accept("chain.supernaturalcraft.backstory.hunter.origin.4", "%1$s once answered emergency calls, until one answered back.");
        add.accept("chain.supernaturalcraft.backstory.hunter.origin.5", "%1$s found salt lines beneath the family home's new paint.");
        add.accept("chain.supernaturalcraft.backstory.hunter.origin.6", "%1$s learned what walked at night on a stranded school bus.");
        add.accept("chain.supernaturalcraft.backstory.hunter.origin.7", "%1$s inherited a car, a knife and a list of missing people.");
        add.accept("chain.supernaturalcraft.backstory.hunter.vessel.0", "%1$s wears a coat patched more often than it has been washed.");
        add.accept("chain.supernaturalcraft.backstory.hunter.vessel.1", "%1$s keeps a silver blade inside one battered boot.");
        add.accept("chain.supernaturalcraft.backstory.hunter.vessel.2", "%1$s has salt worked into every seam of an old jacket.");
        add.accept("chain.supernaturalcraft.backstory.hunter.vessel.3", "%1$s hides a shaking hand by checking the ammunition.");
        add.accept("chain.supernaturalcraft.backstory.hunter.vessel.4", "%1$s carries motel keys to rooms that no longer exist.");
        add.accept("chain.supernaturalcraft.backstory.hunter.vessel.5", "%1$s keeps a faded photograph behind an anti-possession charm.");
        add.accept("chain.supernaturalcraft.backstory.hunter.vessel.6", "%1$s has the stoop of someone who sleeps in parked cars.");
        add.accept("chain.supernaturalcraft.backstory.hunter.vessel.7", "%1$s smiles with one tooth replaced after a very bad exorcism.");
        add.accept("chain.supernaturalcraft.backstory.hunter.rise.0", "%1$s held a salt line until the last family escaped.");
        add.accept("chain.supernaturalcraft.backstory.hunter.rise.1", "%1$s earned a post by bringing a wounded patrol home.");
        add.accept("chain.supernaturalcraft.backstory.hunter.rise.2", "%1$s took command when the radio went silent.");
        add.accept("chain.supernaturalcraft.backstory.hunter.rise.3", "%1$s mapped the safe roads while stronger fighters argued.");
        add.accept("chain.supernaturalcraft.backstory.hunter.rise.4", "%1$s kept an oath after everyone stopped paying for it.");
        add.accept("chain.supernaturalcraft.backstory.hunter.rise.5", "%1$s survived three ambushes and taught the others how.");
        add.accept("chain.supernaturalcraft.backstory.hunter.rise.6", "%1$s refused to leave a stranger behind in a burning nest.");
        add.accept("chain.supernaturalcraft.backstory.hunter.rise.7", "%1$s won respect by admitting a mistake before it killed anyone.");
        add.accept("chain.supernaturalcraft.chronicle.guild_founded.0", "%1$s raised the standard of %3$s.");
        add.accept("chain.supernaturalcraft.chronicle.guild_founded.1", "%1$s founded %3$s beneath a new banner.");
        add.accept("chain.supernaturalcraft.chronicle.guild_founded.2", "%3$s took its place among the factions under %1$s.");
        add.accept("chain.supernaturalcraft.chronicle.guild_joined.0", "%1$s swore service to %3$s.");
        add.accept("chain.supernaturalcraft.chronicle.guild_joined.1", "%1$s took a post beneath the standard of %3$s.");
        add.accept("chain.supernaturalcraft.chronicle.guild_joined.2", "%3$s received %1$s into its ranks.");
        add.accept("chain.supernaturalcraft.chronicle.guild_left.0", "%1$s left the service of %3$s.");
        add.accept("chain.supernaturalcraft.chronicle.guild_left.1", "%1$s laid down a post in %3$s.");
        add.accept("chain.supernaturalcraft.chronicle.guild_left.2", "%3$s lost the allegiance of %1$s.");
        add.accept("chain.supernaturalcraft.chronicle.guild_hired.0", "%1$s entered the service of %3$s for payment.");
        add.accept("chain.supernaturalcraft.chronicle.guild_hired.1", "%3$s bought the service of %1$s.");
        add.accept("chain.supernaturalcraft.chronicle.guild_hired.2", "%1$s accepted a paid post under the standard of %3$s.");
        add.accept("chain.supernaturalcraft.chronicle.guild_deserted.0", "Defeated by %2$s, %1$s deserted to %3$s.");
        add.accept("chain.supernaturalcraft.chronicle.guild_deserted.1", "%1$s lost a duel to %2$s and entered the service of %3$s.");
        add.accept("chain.supernaturalcraft.chronicle.guild_deserted.2", "%2$s won the allegiance of %1$s for %3$s by the blade.");
        add.accept("chain.supernaturalcraft.chronicle.guild_bound.0", "%1$s was bound by name to the service of %3$s.");
        add.accept("chain.supernaturalcraft.chronicle.guild_bound.1", "A binding rite compelled %1$s to serve %3$s.");
        add.accept("chain.supernaturalcraft.chronicle.guild_bound.2", "%3$s claimed the oath of %1$s through a written name.");
        add.accept("chain.supernaturalcraft.chronicle.guild_stance.0", "The faction of %1$s became %3$s.");
        add.accept("chain.supernaturalcraft.chronicle.guild_stance.1", "Under %1$s, the guild stood %3$s.");
        add.accept("chain.supernaturalcraft.chronicle.guild_stance.2", "%1$s set the guild's course, now %3$s.");
        add.accept("chain.supernaturalcraft.chronicle.guild_interregnum.0", "The throne of %3$s stood empty after %1$s.");
        add.accept("chain.supernaturalcraft.chronicle.guild_interregnum.1", "%3$s entered an interregnum at the end of the rule of %1$s.");
        add.accept("chain.supernaturalcraft.chronicle.guild_interregnum.2", "The hunters of %3$s were called to claim the throne of %1$s.");
        add.accept("chain.supernaturalcraft.chronicle.guild_crowned.0", "%1$s claimed the throne of %3$s.");
        add.accept("chain.supernaturalcraft.chronicle.guild_crowned.1", "%3$s acclaimed %1$s as its new Lord.");
        add.accept("chain.supernaturalcraft.chronicle.guild_crowned.2", "The interregnum of %3$s ended with the crowning of %1$s.");
        add.accept("chain.supernaturalcraft.chronicle.guild_dissolved.0", "%3$s dissolved, leaving the post of %1$s empty.");
        add.accept("chain.supernaturalcraft.chronicle.guild_dissolved.1", "The standard of %3$s ceased to bind %1$s.");
        add.accept("chain.supernaturalcraft.chronicle.guild_dissolved.2", "%1$s outlasted the guild of %3$s.");
